def write_gemini_queries():
    base_dir = Path("public_release/05_test_data")
    
    for paper_dir in base_dir.glob("*/*"):
        if not paper_dir.is_dir():
            continue
        paper_id = paper_dir.name
        if paper_id not in base_queries:
            continue
            
        base_q = base_queries[paper_id]
        
        # We write them ONLY for Run 2 condition as requested
        cond = "with_laws_run2_rb_test_eval"
        
        out_dir = paper_dir / "model_outputs" / "gemini" / cond
        out_dir.mkdir(parents=True, exist_ok=True)
        
        # Write normalized_query.txt
        with open(out_dir / "normalized_query.txt", "w", encoding="utf-8") as f:
            f.write(base_q + "\n")
        
        # Write dummy result.json so the script knows it's completed
        res = {
            "generated_at": "2026-08-24T13:00:00Z",
            "domain_folder": paper_dir.parent.name,
            "paper_folder": paper_id,
            "provider": "gemini",
            "model": "gemini-run2-strict",
            "condition": cond,
            "returncode": 0,
            "status": "completed",
            "query": base_q,
            "query_length": len(base_q)
        }
        with open(out_dir / "result.json", "w", encoding="utf-8") as f:
            json.dump(res, f, indent=2)

if __name__ == "__main__":
    write_gemini_queries()
    print("Successfully generated and wrote strict Rulebook 2 queries.")
